package main

import (
	"math"
	"testing"
)

// TestParseTV is the table test for the pure TV-filename parser (B6, INV5). It
// exercises SxxExx extraction, multi-episode, title cleaning, resolution +
// release-group stripping, year, the Cyrillic-title first-class case, and the
// no-season + no-title fallbacks with their confidence tiers.
func TestParseTV(t *testing.T) {
	tests := []struct {
		name       string
		rel        string
		title      string
		season     int64
		episode    int64
		episodeEnd int64
		hasEnd     bool
		resolution string
		group      string
		conf       float64
	}{
		{
			name: "basic SxxExx with title", rel: "Breaking Bad S01E01.mkv",
			title: "Breaking Bad", season: 1, episode: 1, conf: 1.0,
		},
		{
			name: "cyrillic title first-class", rel: "Игра престолов S01E01.mkv",
			title: "Игра престолов", season: 1, episode: 1, conf: 1.0,
		},
		{
			name:  "dot separators + resolution + group + multi-episode",
			rel:   "Show.S01E01E02.1080p.WEB-DL.x264-RG.mkv",
			title: "Show", season: 1, episode: 1, episodeEnd: 2, hasEnd: true,
			resolution: "1080p", group: "RG", conf: 1.0,
		},
		{
			name: "title from full relative path", rel: "Breaking Bad/Season 1/Breaking Bad S01E02.mkv",
			title: "Breaking Bad", season: 1, episode: 2, conf: 1.0,
		},
		{
			name: "720p resolution lowercase", rel: "Anime s02e05 [720p].mp4",
			title: "Anime", season: 2, episode: 5, resolution: "720p", conf: 1.0,
		},
		{
			name: "no season episode -> title only low confidence", rel: "Random Movie.mkv",
			title: "Random Movie", season: 0, episode: 0, conf: 0.3,
		},
		{
			name: "season episode without title -> parent dir fallback", rel: "Some Show/S01E01.mkv",
			title: "Some Show", season: 1, episode: 1, conf: 1.0,
		},
		{
			name: "season episode bare filename no parent -> mid confidence", rel: "S01E01.mkv",
			title: "", season: 1, episode: 1, conf: 0.6,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			parsed, conf, parser := parseTV(tc.rel)
			if parser != "tv-filename" {
				t.Fatalf("parser = %q, want tv-filename", parser)
			}
			if got := strField(parsed, "title"); got != tc.title {
				t.Errorf("title = %q, want %q", got, tc.title)
			}
			if got := numField(parsed, "season"); got != tc.season {
				t.Errorf("season = %d, want %d", got, tc.season)
			}
			if got := numField(parsed, "episode"); got != tc.episode {
				t.Errorf("episode = %d, want %d", got, tc.episode)
			}
			gotEnd, hasEnd := parsed.GetFields()["episode_end"]
			if tc.hasEnd {
				if !hasEnd || int64(gotEnd.GetNumberValue()) != tc.episodeEnd {
					t.Errorf("episode_end = %v (has=%v), want %d", gotEnd, hasEnd, tc.episodeEnd)
				}
			} else if hasEnd {
				t.Errorf("episode_end unexpectedly present = %v", gotEnd)
			}
			if tc.resolution != "" {
				if got := strField(parsed, "resolution"); got != tc.resolution {
					t.Errorf("resolution = %q, want %q", got, tc.resolution)
				}
			}
			if tc.group != "" {
				if got := strField(parsed, "release_group"); got != tc.group {
					t.Errorf("release_group = %q, want %q", got, tc.group)
				}
			}
			if math.Abs(conf-tc.conf) > 1e-9 {
				t.Errorf("confidence = %v, want %v", conf, tc.conf)
			}
		})
	}
}
